def extract_values(node: Node) -> List[str]:
    values = []
    seen = set()
    for module in node.modules:
        if key in module.module_params and module.module_params[key] not in seen:
            values.append(module.module_params[key])
            seen.add(module.module_params[key])
    return values

unique_values = []
for node in nodes:
    unique_values.extend(extract_values(node))
return unique_values

