import jax.numpy as jnp

def generate_safe_fn(f, df, bounds):
  def safe_fn(x):
    if x < bounds[0]:
      return f(bounds[0]) + df(bounds[0], 0, 1) * (x - bounds[0])
    elif x > bounds[1]:
      return f(bounds[1]) + df(bounds[1], 0, 1) * (x - bounds[1])
    else:
      return f(x)
  return safe_fn

